package com.ailab.system.report.provider;
import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import java.util.*; import org.springframework.stereotype.Component;
/** Manual content is renderer-owned; this provider only exposes the validated placeholder as inert text. */
@Component public final class ManualSummaryProvider extends AbstractLabDataSourceProvider { public ManualSummaryProvider(){super(ReportConfigCatalog.MANUAL_SUMMARY,new LinkedHashSet<String>(Arrays.asList("sectionCode")));} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){Map<String,Object>x=new LinkedHashMap<String,Object>();Object placeholder=s.getRenderConfig().get("placeholder");x.put("placeholder",placeholder==null?"":String.valueOf(placeholder));x.put("manual",Boolean.TRUE);return section(c,s,Collections.<Map<String,Object>>emptyList(),x);}}
